import {PRODUCTS} from './product-catalog.js';
import {createProduct} from './product-models.js';
export function decorateStockroom(w){const a=w.a,steel=a.get('metal'),wood=a.get('wood');for(const cfg of[{x:3,z:17.7,w:2.5,d:1.05},{x:-10.15,z:12.6,w:.9,d:3.4}]){w.solids.push({x:cfg.x,z:cfg.z,w:cfg.w,d:cfg.d});for(const dx of[-cfg.w/2,cfg.w/2])for(const dz of[-cfg.d/2,cfg.d/2])w.box(cfg.x+dx,1.25,cfg.z+dz,.055,2.5,.055,steel);for(const y of[.30,1.03,1.76]){w.box(cfg.x,y,cfg.z,cfg.w+.1,.055,cfg.d+.08,wood);for(let i=0;i<(cfg.x===3&&y>1.7?0:3);i++){const x=cfg.x+(i-1)*cfg.w*.28,z=cfg.z;const h=.30+(i%2)*.13,m=w.box(x,y+.03+h/2,z,cfg.w*.24,h,cfg.d*.75,a.get('paper',[0xa59b7c,0xafa58b,0x9b9b86][i]));w.box(x,y+.034+h,z,.045,.008,cfg.d*.76,a.plain(0x8b7652));const label=w.sign(['HALE / 09','DRY GOODS'],x,y+.15,z-cfg.d*.38,cfg.w*.17,Math.PI,{aspect:1.8,bg:'#bfb99f',fg:'#383d30'});}}}const ids=['water','glassSoda','milk','soup','beans','coffeeTin','chips','crackers','nutJar','tissues','bulb','batteries'];for(let i=0;i<ids.length;i++){const m=createProduct(a,ids[i]);m.position.set(2.15+(i%6)*.32,1.7875+PRODUCTS[ids[i]].h/2,17.37+Math.floor(i/6)*.33);w.scene.add(m);}}
